"""Annual operating-company cash-flow reading room and local worksheet pages.

outputs(root, examples=None) returns {Path: html}; it never writes files.
Optional example: {id, label, sourceLabel, values}; values match the JS engine keys.
"""
from pathlib import Path
import json
from education import E, shell, section_head

VERSION = 'operating-1.0.1'
SEC_GUIDE = 'https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements'
SEC_NONGAAP = 'https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/non-gaap-financial-measures'
PAGES = (
    ('operating-companies', 'Operating companies: follow the cash'),
    ('operating-cash-flow-guide', 'From net income to operating cash flow'),
    ('dividends-buybacks-guide', 'Dividends, buybacks and the cash left over'),
    ('cash-flow-workbench', 'Operating cash-flow workbench'),
)


def top(slug, title, description, kicker='Operating companies / annual cash-flow analysis'):
    crumb = '<a href="/operating-companies.html">Operating companies</a><span>/</span>' if slug != 'operating-companies' else ''
    return f'<div class="wrap breadcrumbs"><a href="/">Home</a><span>/</span>{crumb}<span aria-current="page">{E(title)}</span></div>' + section_head(kicker, E(title), description)


def sources():
    return f'''<section id="sources"><h2>Sources, scope and next steps</h2><p>This material covers annual statements for US nonfinancial operating companies, using US GAAP presentation and one reporting currency. The workbench fixes the unit at USD million. Banks, insurers, REITs and BDCs require different analytical frameworks; cross-border accounting classifications also need separate review. Examples are synthetic unless an identified historical filing is loaded.</p><ul class="source-list"><li><a href="{SEC_GUIDE}">SEC: Beginners’ Guide to Financial Statements</a> — the cash-flow statement and its relationship to earnings.</li><li><a href="{SEC_NONGAAP}">SEC staff: Non-GAAP Financial Measures, Question 102.07</a> — explain the FCF definition and its limitations; other obligations may remain after capital expenditures.</li></ul><p class="small-note">Source guidance checked October 18, 2026. DFB’s worksheet arithmetic and teaching examples are its own. Educational analysis, not an issuer rating, a forecast or individualized advice. <a href="/editorial-policy.html">Editorial policy</a> · <a href="mailto:dividendforensics@gmail.com?subject=Operating%20company%20correction">Report a source or calculation correction</a>.</p></section>'''


def page(root, slug, title, description, body, workbench=False):
    extra = '<link rel="stylesheet" href="/operating-companies.css?v=operating-1.0.0">'
    if workbench:
        extra += f'<script src="/vendor/decimal.js/decimal.js" defer></script><script src="/operating-calculators.js?v={VERSION}" defer></script>'
    return shell(root, slug+'.html', title, description, body, 'CollectionPage' if slug == 'operating-companies' else 'WebPage', extra=extra)


def hub(root):
    slug,title=PAGES[0]
    description='Follow earnings into operating cash, define your capital-spending deduction, and reconcile dividends and buybacks with the full cash statement.'
    body=top(slug,title,description)
    from stock_basics import prerequisite_links
    body+=prerequisite_links()
    body+='''<section class="wrap ocf-section"><span class="kicker">A new starting point beyond REITs and BDCs</span><h2>One year. Two bridges. Four questions.</h2><p>A manufacturer, software business or consumer company can report rising earnings while cash generation weakens. It can also distribute more cash than a particular free-cash-flow definition produced during the year. Neither observation explains the cause on its own. Start by rebuilding the statement, then separate the accounting reconciliation from your interpretation of capital allocation.</p><div class="ocf-map" aria-label="The operating-company analysis sequence"><div><span>01 / EARNINGS</span><strong>What was earned?</strong><p>Start with the net-income line used in the operating cash reconciliation.</p></div><div><span>02 / OPERATIONS</span><strong>What became cash?</strong><p>Preserve the signs of adjustments and operating assets and liabilities.</p></div><div><span>03 / ALLOCATION</span><strong>What was spent?</strong><p>Deduct defined PP&E purchases, then actual dividends and repurchases.</p></div><div><span>04 / BALANCE</span><strong>Where did cash go?</strong><p>Reconcile all reported categories to the ending cash balance.</p></div></div><p>The earnings-to-cash bridge helps explain the source of operating cash flow. The beginning-to-ending cash bridge captures investing, financing and currency effects as well. A residual from the first bridge is not the change in the bank balance.</p></section>
<section class="wrap ocf-section"><h2>Read, build, then interrogate the result.</h2><div class="ocf-route-grid"><article class="ocf-route"><span class="kicker">01 / Read the statement</span><h3><a href="/operating-cash-flow-guide.html">Earnings to operating cash</a></h3><p>Signs, working-capital timing and the difference between a noncash add-back and an economic cost. Includes a complete 120 → 135 reconciliation.</p><a class="text-link" href="/operating-cash-flow-guide.html">Read the first guide →</a></article><article class="ocf-route"><span class="kicker">02 / Follow the allocation</span><h3><a href="/dividends-buybacks-guide.html">Dividends and repurchases</a></h3><p>Define FCF, count payments in the right period and explain a negative residual without inventing a funding story.</p><a class="text-link" href="/dividends-buybacks-guide.html">Read the second guide →</a></article><article class="ocf-route"><span class="kicker">03 / Work the numbers</span><h3><a href="/cash-flow-workbench.html">The cash-flow workbench</a></h3><p>Edit a signed bridge, inspect exact totals, check ending cash and export the input trail. Computation stays in your browser tab.</p><a class="text-link" href="/cash-flow-workbench.html">Open the workbench →</a></article></div></section>
<section class="wrap ocf-section lesson-body"><h2>Collect the evidence before entering numbers.</h2><div class="ocf-table-scroll" tabindex="0" role="region" aria-label="Source collection checklist"><table class="ocf-table"><caption>Use one annual column and the same consolidation perimeter throughout.</caption><thead><tr><th scope="col">Source location</th><th scope="col">Bring into the worksheet</th><th scope="col">Question to retain</th></tr></thead><tbody><tr><th scope="row">Statement of cash flows</th><td>Net income; every operating adjustment; reported OCF</td><td>Do all entered components sum to the published total?</td></tr><tr><th scope="row">Investing section</th><td>Cash PP&E purchases and the full signed investing total</td><td>What acquisitions, asset sales or securities movements sit outside PP&E purchases?</td></tr><tr><th scope="row">Financing section</th><td>Paid dividends, paid share repurchases, and the full financing total</td><td>Are announcements, unsettled purchases or noncash transactions being confused with cash paid?</td></tr><tr><th scope="row">Cash reconciliation and notes</th><td>Beginning and ending cash under the identical definition; currency effects</td><td>Does the statement include restricted cash that the balance-sheet headline excludes?</td></tr></tbody></table></div><p>Preserve source labels next to your grouped inputs. An issuer’s “other” adjustment is not automatically noncash; a signed subtotal must still be traceable to the individual source rows. A zero requires evidence. A missing number stays missing.</p><h2>Build an explanation, not a score.</h2><p>After the arithmetic reconciles, compare several complete annual periods and read the liquidity discussion. Investigate whether cash improved through stronger trading, delayed supplier payments, reduced inventory, disposals or new borrowing. A single year cannot distinguish a durable improvement from timing. Research reinvestment commitments and debt maturities separately; the workbench does not estimate them.</p><p>For property and lending businesses, use the <a href="/learn.html">REIT curriculum</a> or <a href="/learn-bdc.html">BDC curriculum</a>. For a source record across sectors, use the <a href="/dividend-research-worksheet.html">research worksheet</a>. The <a href="/filing-labs.html">filing labs</a> connect the lessons to historical disclosures.</p>'''+sources()+'</section>'
    return page(root,slug,title,description,body)


def reader(root, index, description, sections):
    slug,title=PAGES[index]
    nav=''.join(f'<li><a href="#{ident}">{E(heading)}</a></li>' for ident,heading,_ in sections)
    content=''.join(f'<section id="{ident}"><h2>{E(heading)}</h2>{body}</section>' for ident,heading,body in sections)
    body=top(slug,title,description)+f'<div class="wrap article-meta">DFB Education · Annual US operating companies · Updated October 18, 2026</div><div class="wrap ocf-reader"><aside><span class="kicker">In this guide</span><ol>{nav}<li><a href="#sources">Sources and scope</a></li></ol><a class="text-link" href="/cash-flow-workbench.html">Open the workbench →</a></aside><article class="lesson-body">{content}{sources()}</article></div>'
    return page(root,slug,title,description,body)


def operating_guide(root):
    sections=[
        ('start','Start with the correct net-income line','''<p>Use the net-income figure at the top of the issuer’s indirect operating cash-flow reconciliation. Do not substitute earnings per share, operating profit or an adjusted earnings number. Check whether the cash-flow statement begins with consolidated net income and whether discontinued operations are included. A common-share earnings measure can have a different perimeter.</p><p>Copy one full annual column. Record its fiscal year, beginning and ending dates, currency and scale. A retailer’s 52-week year and a calendar year can describe different activity; year-to-date quarterly figures cannot be silently mixed with an annual dividend total. The workbench is deliberately limited to annual USD million inputs.</p>'''),
        ('signs','Read adjustments as signed changes','''<p>Under the indirect presentation, begin with net income and add each reconciliation entry with the sign shown in the statement. A depreciation add-back reverses an expense that reduced earnings without that period’s corresponding cash payment. A gain on an asset sale may be subtracted from the operating reconciliation while the cash proceeds appear in investing.</p><p>Keep noncash and other reconciliation adjustments distinct from changes in operating assets and liabilities. Grouping source rows makes a worksheet easier to read, but the underlying list must remain available. An issuer’s unitemized “other” row does not prove that every item within it is noncash.</p><div class="ocf-ledger"><span class="kicker">Exact bridge definition</span><p class="ocf-equation">Net income + signed reconciliation adjustments + signed operating asset / liability changes = reconstructed OCF</p><p>Reconstructed OCF − reported OCF = reconciliation gap. A gap of zero establishes an arithmetic match to the entered total, not completeness of the source or correctness of its accounting.</p></div>'''),
        ('timing','Working capital can change the story','''<p>Receivables may rise because revenue has been recognized before customers pay. Inventory purchases can absorb cash before products are sold. Payables can provide temporary cash when payment to suppliers follows recognition of purchases or expenses. The cash-flow statement records the effects relevant to its operating reconciliation.</p><p>Use those cash-flow effects directly. Do not replace them with a naive subtraction of two balance-sheet totals: acquisitions, disposals, foreign currency translation and noncash changes can make the balance-sheet movement differ. A positive payable adjustment does not by itself establish delayed payment, and a receivable outflow does not by itself establish poor collectability. Read the notes and management discussion to identify the cause.</p><p>Tax payments, settlements and other operating liabilities can be large. The workbench’s second signed group therefore says “working-capital / other operating changes.” It is not a claim that every included item belongs to a narrow textbook working-capital definition.</p>'''),
        ('example','Work the synthetic annual statement','''<div class="ocf-table-scroll" tabindex="0" role="region" aria-label="Synthetic operating reconciliation"><table class="ocf-table"><caption>Synthetic manufacturer · fiscal year 2024 · USD million</caption><thead><tr><th scope="col">Source row</th><th scope="col">Signed amount</th><th scope="col">Running total</th></tr></thead><tbody><tr><th scope="row">Net income</th><td>120</td><td>120</td></tr><tr><th scope="row">Depreciation and other reconciliation adjustments</th><td>+40</td><td>160</td></tr><tr><th scope="row">Receivables</th><td>−20</td><td>140</td></tr><tr><th scope="row">Inventory</th><td>−15</td><td>125</td></tr><tr><th scope="row">Payables and other operating changes</th><td>+10</td><td>135</td></tr><tr><th scope="row">Reported operating cash flow</th><td>135</td><td>Gap: 0</td></tr></tbody></table></div><p>The operating changes sum to −25. The workbench therefore takes 120, +40 and −25, producing OCF of 135. If you accidentally enter +25, reconstructed OCF becomes 185 and the gap to the reported 135 is +50. A sign mistake can double the apparent effect of a cash outflow.</p><details class="workshop-answer"><summary>Try it: receivables consume another 30. What changes?</summary><p>Hold every other component constant. The signed operating-change group becomes −55 and reconstructed OCF falls to 105. If reported OCF stays 135, the scenario has a −30 reconciliation gap; it is no longer a reproduction of the original statement. To model a consistent alternative annual statement, update the reported OCF and reconcile the cash bridge too.</p></details>'''),
        ('limits','Cash conversion still needs interpretation','''<p>An add-back does not erase an economic cost. Share-based compensation can dilute owners even when it is added back to operating cash flow; depreciation can reflect assets that will need replacement. Neither item creates a promise that the amount will be available for dividends.</p><p>Negative net income with positive OCF can result from large noncash charges or operating timing effects. Positive earnings with negative OCF can result from investment in inventory or slower collections. Preserve those signs and investigate the business context. This worksheet intentionally avoids a ratio with a zero or negative denominator and does not translate a total into a safety label.</p><p>Next, move from the reconciled operating result to <a href="/dividends-buybacks-guide.html">capital spending, dividends and repurchases</a>. Retain the full investing and financing totals: the ending cash balance cannot be explained by operating cash alone.</p>'''),
    ]
    return reader(root,1,'Rebuild the indirect cash-flow statement, preserve adjustment signs, and distinguish cash timing from a durable change in the business.',sections)


def distributions_guide(root):
    sections=[
        ('define','Write the free-cash-flow definition first','''<p>In this worksheet, user-defined free cash flow equals reconstructed operating cash flow minus cash purchases of property, plant and equipment. Enter PP&E purchases as a positive amount; the workbench subtracts them. This is a specific analytical definition, not a standardized GAAP subtotal or a claim that the issuer uses the same measure.</p><p>Use the cash purchase line from the investing section. A balance-sheet increase in PP&E can include noncash additions and accounting changes. Do not automatically net asset-sale proceeds against purchases. Software investment, acquisitions, leased assets and other spending can sit elsewhere or receive different treatment under another FCF definition. Preserve those differences when comparing companies.</p><div class="ocf-ledger"><p class="ocf-equation">User-defined FCF = reconstructed OCF − cash PP&E purchases</p><p>For the synthetic company: 135 − 55 = 80 USD million.</p></div><p>The SEC staff’s guidance in Question 102.07 calls for a clear definition and reconciliation and cautions against treating FCF as cash available for discretionary uses. Debt service and other commitments can remain. Our residual below is therefore a deliberately narrow arithmetic remainder.</p>'''),
        ('payments','Use paid cash, not an authorization','''<p>Collect the cash dividends and cash share repurchases for the same annual period. A board authorization is permission to repurchase, not evidence of cash spent. A declaration date, annualized dividend rate or future announced increase cannot replace the year’s cash payments. If the source combines common and preferred dividends, preserve that combined scope rather than silently relabeling it common-only.</p><p>Repurchase accounting can involve settlement timing, accelerated agreements and excise taxes. Copy the disclosed cash line and record what it includes. The change in treasury stock or the share count is not a reliable cash substitute. Repurchases can offset new issuance, and fewer shares can increase per-share figures even when total earnings are unchanged.</p><p>The workbench adds the entered cash dividends and share repurchases, then subtracts that total from its FCF definition. It does not calculate shareholder return, determine whether repurchases were well priced, or assume the cash reached a particular investor.</p>'''),
        ('residual','Interpret a negative residual carefully','''<div class="ocf-ledger"><span class="kicker">Synthetic annual allocation · USD million</span><p class="ocf-equation">80 FCF − 30 dividends − 65 buybacks = −15 residual</p><p>Dividends alone leave 50 under this definition; adding repurchases produces a shortfall of 15.</p></div><p>This statement tells you that the two entered payments exceeded the defined annual FCF by 15. It does not identify a particular financing source. Cash is fungible: beginning cash, borrowing, asset disposals and securities movements may all contribute to the company’s overall cash position.</p><p>Nor does one negative year predict a dividend cut. Investigate whether the business used previously accumulated cash, executed a temporary capital program or made a discretionary repurchase. A positive residual needs equal care: contractual payments, acquisition commitments and minimum operating liquidity are not all represented in this FCF definition.</p><details class="workshop-answer"><summary>Try it: repurchases fall from 65 to 20. What can you conclude?</summary><p>The residual rises from −15 to +30, a change of +45. The company used 45 less cash for repurchases in the scenario. That alone does not demonstrate improved operating performance: OCF remains 135 and FCF remains 80. Keep operating generation and capital-allocation decisions separate in your explanation.</p></details>'''),
        ('cash','Reconcile the actual change in cash','''<p>Return to the statement’s reported OCF, net investing and net financing categories. Use the signed net totals. The investing total already includes cash PP&E purchases; the financing total already includes the cash dividends and repurchases classified there. Subtracting those individual amounts again would double-count them.</p><div class="ocf-ledger"><p class="ocf-equation">100 beginning cash + 135 OCF − 45 net investing − 85 net financing − 2 FX = 103 ending cash</p><p>Synthetic investing: −55 PP&E + 10 asset-sale proceeds = −45. Synthetic financing: −30 dividends −65 repurchases +10 net borrowing = −85. Net cash increased by 3 although the narrower residual was −15.</p></div><p>Match the beginning and ending cash definitions exactly. If the statement includes restricted cash, use that same aggregate at both endpoints and check its reconciliation to the balance sheet. A currency effect belongs in its own cash reconciliation entry; do not treat it as operating generation. An omitted FX line is not automatically proof that a separate reported amount was zero.</p><p>The workbench reports calculated ending cash less reported ending cash as a second gap. It uses reported OCF here even when the earnings bridge has a discrepancy, allowing you to see which reconciliation fails. A matched cash balance does not cure an unreconciled earnings bridge.</p>'''),
        ('research','Turn the result into the next research task','''<p>Write three short sentences: what operating cash changed, how the company allocated cash, and what remains unexplained. Attach a period and a source to each. For example: “In this synthetic year, operating cash was 135 after a 25 operating-asset/liability outflow. PP&E purchases and shareholder payments exceeded it by 15. Asset-sale proceeds, net borrowing and currency effects explain why cash nevertheless rose by 3.”</p><p>Then inspect the maturity schedule, reinvestment requirements, financing terms and subsequent disclosures. Repeat the exercise for comparable years without mixing definitions. Use the <a href="/cash-flow-workbench.html">workbench</a> to keep a baseline, change a single assumption and compare exact arithmetic deltas. A scenario can expose a dependency; it cannot establish that the dependency will occur.</p>'''),
    ]
    return reader(root,2,'Define a cash-flow remainder, separate actual shareholder payments from announcements, and reconcile the result to the change in cash.',sections)


FIELDS=[
    ('scenarioLabel','Scenario / source label','Synthetic manufacturer · annual exercise','Name the source or label the scenario as synthetic.'),
    ('fiscalYear','Annual fiscal year','2024','One complete annual period; align every cash-flow input.'),
    ('cashDefinition','Beginning / ending cash definition','Cash and cash equivalents; no restricted cash in this synthetic example','Use the same source definition at both endpoints, including restricted cash if applicable.'),
    ('netIncome','Net income','120','Signed amount from the first line of the operating reconciliation.'),
    ('noncash','Noncash and other reconciliation adjustments','40','Signed sum. Keep the underlying rows; an issuer’s “other” entry may not be entirely noncash.'),
    ('workingCapital','Working-capital / other operating changes','-25','Signed sum from the cash-flow statement, not a naive balance-sheet difference.'),
    ('reportedOCF','Reported operating cash flow (optional)','135','Leave blank if unknown. Required to check either reconciliation.'),
    ('capex','Cash PP&E purchases','55','Positive cash outflow; subtracted once to define FCF. Do not net asset-sale proceeds.'),
    ('dividends','Cash dividends paid','30','Positive paid amount for this year; retain common / preferred scope.'),
    ('buybacks','Cash share repurchases','65','Positive actual cash payment, not an authorization.'),
    ('beginningCash','Beginning cash','100','Positive or zero; use the cash definition entered above.'),
    ('netInvesting','Net investing cash flow','-45','Signed reported total; it already includes cash PP&E purchases.'),
    ('netFinancing','Net financing cash flow','-85','Signed reported total; it already includes dividends and share repurchases.'),
    ('fx','Currency / other cash reconciliation effect','-2','Signed separately disclosed effect. A zero convention must be documented if no separate line exists.'),
    ('endingCash','Reported ending cash','103','Positive or zero; matches the beginning-cash definition.'),
]


def workbench(root, examples=None):
    slug,title=PAGES[3]
    description='Rebuild annual operating cash flow, define FCF, inspect dividends and buybacks, and reconcile the ending cash balance. Exact local arithmetic, editable scenarios and CSV.'
    body=top(slug,title,description)
    body+='''<section class="wrap"><p class="education-lede">Annual US nonfinancial operating companies · all amounts in USD million. Enter plain decimals with a period. Signed adjustments can be negative; payment fields are positive amounts that the worksheet subtracts.</p></section><div class="wrap ocf-workbench"><form class="calculator-form ocf-form" data-operating-workbench novalidate><fieldset data-calculator-controls data-operating-controls disabled><legend>Your annual statement</legend><p class="calculator-loading" data-calculator-loading data-operating-loading>Controls unlock when the local calculation scripts finish loading. If they remain disabled, use the formulas and complete worked example below.</p><p><strong>Synthetic default; not company data.</strong> Inputs and baseline comparisons remain in this tab’s memory. No data is sent or saved. Reloading discards edits. No rating or safety threshold is assigned.</p><label for="operating-preset">Example to load<select id="operating-preset" data-operating-preset></select></label><button type="button" class="btn btn-s" data-operating-load>Load selected example</button><p data-operating-source>Illustrative data, not an issuer.</p>'''
    for key,label,value,hint in FIELDS:
        if key=='netIncome': body+='<h2>1. Earnings → operating cash</h2>'
        if key=='capex': body+='<h2>2. Capital spending → shareholder cash</h2>'
        if key=='beginningCash': body+='<h2>3. Check the cash balance</h2><p>Enter all five balance-bridge fields, or leave all five blank. Reported OCF above is required. Do not subtract capital spending or shareholder payments again.</p>'
        numeric=key not in ('scenarioLabel','fiscalYear','cashDefinition')
        required='' if key in ('reportedOCF','beginningCash','netInvesting','netFinancing','fx','endingCash') else ' required'
        body+=f'<label for="operating-{key}">{E(label)}<input id="operating-{key}" name="{key}" type="text" value="{E(value)}" maxlength="{48 if numeric else 240}"{(" inputmode=\"decimal\"" if numeric else "")}{required} aria-describedby="operating-hint-{key}"><small id="operating-hint-{key}">{E(hint)}</small></label>'
    body+='''<div class="btns"><button type="submit" class="btn btn-p">Recalculate</button><button type="reset" class="btn btn-s">Reset synthetic example</button></div><p class="ocf-error calculator-error" role="alert" tabindex="-1" data-operating-error hidden></p><noscript><p>JavaScript is required for editing. The complete formulas, signs and example below remain available.</p></noscript></fieldset></form><section class="ocf-output" aria-label="Operating cash-flow worksheet results"><h2>Trace every step.</h2><p class="ocf-live" role="status" aria-live="polite" data-operating-status>Local calculation has not started.</p><div data-operating-result><p>No live results yet. Read the worked example below while the scripts load.</p></div><div class="btns"><button type="button" class="btn btn-s" data-operating-baseline disabled>Keep current as baseline</button><button type="button" class="btn btn-s" data-operating-clear disabled>Clear baseline</button><button type="button" class="btn btn-s" data-operating-export disabled>Export exact results CSV</button></div><div data-operating-comparison></div></section></div>
<article class="wrap lesson-body ocf-section"><section id="formula"><span class="kicker">Readable without JavaScript</span><h2>Formulas and a complete synthetic worked example</h2><p>Reconstructed OCF = net income + signed noncash and other reconciliation adjustments + signed working-capital / other operating changes. OCF gap = reconstructed OCF − reported OCF. User-defined FCF = reconstructed OCF − cash PP&E purchases. Shareholder cash payments = cash dividends paid + cash share repurchases. Residual = user-defined FCF − shareholder cash payments.</p><p>The cash balance bridge uses beginning cash + reported OCF + signed net investing + signed net financing + signed currency / other cash reconciliation effect. Cash gap = calculated ending cash − reported ending cash. Do not substitute FCF for reported OCF in that equation; PP&E purchases are already in net investing.</p><div class="ocf-table-scroll" tabindex="0" role="region" aria-label="Complete default synthetic calculation"><table class="ocf-table"><caption>Synthetic manufacturer, annual fiscal year 2024 · USD million</caption><thead><tr><th scope="col">Calculation</th><th scope="col">Exact result</th><th scope="col">What the result means</th></tr></thead><tbody><tr><th scope="row">120 net income + 40 adjustments − 25 operating changes</th><td>135 OCF</td><td>Matches entered reported OCF of 135; gap 0.</td></tr><tr><th scope="row">135 OCF − 55 cash PP&E purchases</th><td>80 user-defined FCF</td><td>A non-GAAP worksheet definition, not all available cash.</td></tr><tr><th scope="row">30 cash dividends + 65 cash repurchases</th><td>95 shareholder cash payments</td><td>Actual assumed annual payments; no authorization amounts.</td></tr><tr><th scope="row">80 FCF − 95 payments</th><td>−15 residual</td><td>Payments exceed this definition by 15; no funding source is inferred.</td></tr><tr><th scope="row">100 beginning + 135 operating − 45 investing − 85 financing − 2 FX</th><td>103 ending cash</td><td>Matches entered ending cash of 103; gap 0. Cash increased by 3.</td></tr></tbody></table></div><p>The −45 investing total consists of −55 PP&E purchases and +10 asset-sale proceeds. The −85 financing total consists of −30 dividends, −65 repurchases and +10 net borrowing. This explains why a −15 residual can coexist with a +3 change in cash: the two calculations include different items.</p></section>
<section><h2>Explore one change at a time.</h2><ol><li>Keep the synthetic result as a baseline. Reduce repurchases from 65 to 20: shareholder cash falls by 45 and the residual rises to 30.</li><li>The cash balance does not change automatically: financing is an independent reported total. In a consistent hypothetical statement, change net financing from −85 to −40; calculated ending cash becomes 148.</li><li>If reported ending cash remains 103, the second reconciliation gap is +45. Update that endpoint only when constructing the complete hypothetical scenario, never to conceal a discrepancy in a real source.</li></ol><p>A baseline stores the input labels, amounts and calculated values in memory. Comparison deltas are current minus baseline. Reset restores the synthetic inputs; a saved baseline remains until you clear it or reload the tab. Export includes the current inputs, results and any retained comparison.</p></section>
<section><h2>Assumptions and limitations</h2><p>Enter zero only when supported; a blank required input blocks the result. Reported OCF can be left blank, but its reconciliation and the cash balance check are then unavailable. All five cash balance fields may be omitted together. Negative OCF, FCF and residuals are preserved. There is no payout ratio or division by a zero or negative cash-flow total.</p><p>A matching total tests arithmetic only. Grouped entries can hide offsetting errors. A source reported in rounded millions can itself introduce a small gap; this tool shows it exactly and applies no automatic tolerance. Preserve the original source precision and explain any discrepancy.</p><p>FCF here deducts only the specified cash PP&E purchases. It does not deduct every acquisition, debt repayment, lease commitment or future reinvestment requirement. Stock compensation remains an economic issue even when added back in operating cash flow. Read the <a href="/operating-cash-flow-guide.html">operating cash-flow guide</a> and <a href="/dividends-buybacks-guide.html">dividends and buybacks guide</a> before interpreting the residual.</p><p>Accepted amounts have up to 30 integer and 16 fractional digits. An isolated Decimal arithmetic context uses 80 significant digits; these bounded additions and subtractions retain exact decimal strings. Arithmetic precision does not increase the accuracy of the source inputs. Only visual bar widths are rounded. CSV neutralizes spreadsheet-formula text while retaining numeric negative amounts.</p></section>'''+sources()+'</article>'
    body += '<section class="wrap education-section" aria-labelledby="workbench-related"><h2 id="workbench-related">Related guides and historical filing practice</h2><p>Read the definitions before interpreting a scenario. The filing lab uses a dated annual disclosure, not current company data or a forecast.</p><ul class="workbench-reading-links"><li><a href="/operating-cash-flow-guide.html">Operating cash flow: earnings to cash</a></li><li><a href="/dividends-buybacks-guide.html">Capital spending, dividends and buybacks</a></li><li><a href="/filing-lab-apple-2024.html">Apple FY2024 historical filing lab</a></li></ul></section>'
    payload=json.dumps(examples or [], ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    body+=f'<script id="operating-examples" type="application/json">{payload}</script>'
    return page(root,slug,title,description,body,True)


def outputs(root, examples=None):
    root=Path(root)
    return {root/'operating-companies.html':hub(root),root/'operating-cash-flow-guide.html':operating_guide(root),root/'dividends-buybacks-guide.html':distributions_guide(root),root/'cash-flow-workbench.html':workbench(root,examples)}
